_MISSING = object()


class ApiResponse(Response):
    """Response class that understands JSON payloads.

    Flask 0.12 has no ``Response.get_json()`` -- it only arrived in Flask 1.0 --
    yet reading a JSON body off a response is the natural way to exercise this
    project's REST API.  Provide the later API here so that
    ``response.get_json()`` and ``response.json`` both work.
    """

    @property
    def is_json(self):
        mimetype = self.mimetype or ''
        return mimetype == 'application/json' or (
            mimetype.startswith('application/') and
            mimetype.endswith('+json'))

    def get_json(self, force=False, silent=False, cache=True):
        """Parse and return the response body as JSON.

        :param force: parse regardless of the mimetype.
        :param silent: return ``None`` instead of raising on a parse error.
        :param cache: remember the parsed value for subsequent calls.
        """
        if cache:
            cached = getattr(self, '_cached_json', _MISSING)
            if cached is not _MISSING:
                return cached
        if not (force or self.is_json):
            return None
        try:
            rv = json.loads(self.get_data(as_text=True))
        except ValueError:
            if not silent:
                raise
            rv = None
        if cache:
            self._cached_json = rv
        return rv

    @property
    def json(self):
        return self.get_json()


class ApiTestClient(FlaskClient):
    """Test client that understands the ``json=`` keyword argument.

    Werkzeug 0.12 predates the test client's built-in JSON support, so
    ``client.post(url, json={...})`` would raise ``TypeError``.  Translate it
    into an equivalent body plus content type.
    """

    def open(self, *args, **kwargs):
        if 'json' in kwargs:
            kwargs['data'] = json.dumps(kwargs.pop('json'))
            kwargs.setdefault('content_type', 'application/json')
        return super(ApiTestClient, self).open(*args, **kwargs)

