def _load_token(token):
    """Deserialize a signed token, accepting either ``str`` or ``bytes``.

    :raises Exception: whatever :mod:`itsdangerous` raises for a token that is
        malformed, tampered with or expired.
    """
    s = Serializer(current_app.config['SECRET_KEY'])
    raw = token if isinstance(token, bytes) else str(token).encode('utf-8')
    return s.loads(raw)


